// spec: specs/orders.md §27 · кейс .qa/tests/orders/ord-39-order-details-items-narrow.md (п. 7–8)
// seed: tests/seed.admin.spec.ts
// #ceadd3 (עבר QA 27.10, commit 50258b1): карточка заказа (מפיץ) /orders/<uuid>, итоги блока «פריטי ההזמנה».
//   «מה רצוי»: после последней строки товара — «סכום ביניים» без линии над ней, затем линия-разделитель, затем «סה"כ לתשלום»
//   (Figma 35:222 / 36:278, разделитель 36:321 — 1px на всю ширину контента, 10px до и после).
//   Основная ширина 1440 (таблица); регресс узкой раскладки (комментарий программиста — тот же блок итогов): телефон 320–667,
//   1024–1381 с боковым меню, 705/706 без меню.
// Линии ищутся по вычисленным стилям (border-top/bottom > 0, не прозрачный) у всех элементов карточки, кроме рамки самой карточки.
// Данные: заказ #650 (2 позиции, ₪105.00; поиск по номеру). Только просмотр → @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const ORDER = '650';

async function openOrder650(page: Page) {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await page.getByRole('textbox', { name: 'חיפוש לפי לקוח או מספר הזמנה' }).fill(ORDER);
  const row = page.getByRole('button', { name: new RegExp(`^#${ORDER} `) });
  await expect(row).toBeVisible({ timeout: 30_000 });
  await row.click();
  await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 30_000 });
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${ORDER}` })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText('סה"כ לתשלום', { exact: true }).first()).toBeVisible({ timeout: 20_000 });
}

/** Замер итогов и всех горизонтальных линий карточки «פריטי ההזמנה» (только чтение DOM). */
const measure = (page: Page) => page.evaluate(() => {
  const bx = (e: Element) => { const b = e.getBoundingClientRect(); return { l: b.left, t: b.top, r: b.right, b: b.bottom }; };
  const h = [...document.querySelectorAll('h1,h2,h3,h4')].find((e) => e.textContent!.trim() === 'פריטי ההזמנה')!;
  let card: HTMLElement = h.parentElement!;
  while (!card.querySelector('[class*="@container"]')) card = card.parentElement!;
  const leaf = (t: string) => [...card.querySelectorAll('*')].find((e) => e.children.length === 0 && e.textContent!.trim() === t)!;
  const total = (t: string) => {
    const lab = leaf(t);
    const amt = lab.parentElement!.querySelector('[dir="ltr"]')!;
    const lb = bx(lab), ab = bx(amt);
    return { lab: lb, amt: ab, text: amt.textContent!.trim(), top: Math.min(lb.t, ab.t), bottom: Math.max(lb.b, ab.b), row: bx(lab.parentElement!) };
  };
  const sub = total('סכום ביניים');
  const tot = total('סה"כ לתשלום');
  // низ содержимого строк товаров = самый нижний видимый лист выше «סכום ביניים»
  const cont = card.querySelector('[class*="@container"]')!;
  const itemsBottom = Math.max(...[...cont.querySelectorAll('*')]
    .filter((e) => e.children.length === 0 && e.getClientRects().length > 0 && (e.textContent || '').trim() && e.getBoundingClientRect().bottom <= sub.top + 0.5)
    .map((e) => e.getBoundingClientRect().bottom));
  const lines: { y: number; l: number; r: number; w: number; color: string }[] = [];
  for (const e of card.querySelectorAll('*')) {
    if (!e.getClientRects().length) continue;
    const s = getComputedStyle(e);
    const b = e.getBoundingClientRect();
    const sides = [[s.borderTopWidth, s.borderTopStyle, s.borderTopColor, b.top], [s.borderBottomWidth, s.borderBottomStyle, s.borderBottomColor, b.bottom]] as const;
    for (const [w, st, c, y] of sides) {
      if (parseFloat(w) > 0 && st !== 'none' && st !== 'hidden' && !/rgba\(.*,\s*0\)$/.test(c) && c !== 'transparent') lines.push({ y, l: b.left, r: b.right, w: parseFloat(w), color: c });
    }
  }
  return { vw: innerWidth, docSW: document.documentElement.scrollWidth, card: bx(card), sub, tot, itemsBottom, lines };
});

const rgb = (c: string) => (c.match(/\d+(\.\d+)?/g) || []).slice(0, 3).map(Number);

async function checkTotals(page: Page, W: number, H: number, menuOpen = false) {
  await page.setViewportSize({ width: W, height: H });
  await expect.poll(() => page.evaluate(() => innerWidth)).toBe(W);
  if (menuOpen) await expect(page.getByRole('button', { name: /^כיווץ/ }), `${W}: боковое меню открыто`).toBeVisible();
  await expect(page.getByText('סה"כ לתשלום', { exact: true }).first()).toBeVisible();
  const m = await measure(page);
  const tag = `${W}×${H}`;

  // (Т1) над «סכום ביניים» нет линии: между низом последней строки товара и «סכום ביניים» линий нет (Figma 36:278, «ואין קו נוסף»)
  const above = m.lines.filter((x) => x.y > m.itemsBottom + 0.5 && x.y < m.sub.top - 0.5);
  expect(above, `${tag}: нет линии между последней строкой товара и «סכום ביניים»`).toEqual([]);

  // (Т2) ровно одна линия между «סכום ביניים» и «סה"כ לתשלום»
  const between = m.lines.filter((x) => x.y > m.sub.bottom - 0.5 && x.y < m.tot.top + 0.5);
  expect(between.length, `${tag}: одна линия-разделитель между «סכום ביניים» и «סה"כ לתשלום»`).toBe(1);
  const line = between[0];
  expect(line.w, `${tag}: толщина разделителя 1px (Figma 36:321)`).toBe(1);
  // на всю ширину контента — от края до края строк итогов
  expect(Math.abs(line.l - m.sub.row.l), `${tag}: разделитель от левого края итогов`).toBeLessThanOrEqual(1);
  expect(Math.abs(line.r - m.sub.row.r), `${tag}: разделитель до правого края итогов`).toBeLessThanOrEqual(1);
  // отступы 10px до и после (Figma 36:317 / 36:321; коммент 50258b1)
  expect(Math.round(line.y - m.sub.row.b), `${tag}: от «סכום ביניים» до линии 10px`).toBeGreaterThanOrEqual(9);
  expect(Math.round(line.y - m.sub.row.b), `${tag}: от «סכום ביניים» до линии 10px`).toBeLessThanOrEqual(11);
  const gapBelow = Math.round(m.tot.top - line.y);
  expect(gapBelow, `${tag}: от линии до «סה"כ לתשלום» ~10px (${gapBelow})`).toBeGreaterThanOrEqual(9);
  expect(gapBelow, `${tag}: от линии до «סה"כ לתשלום» ~10px (${gapBelow})`).toBeLessThanOrEqual(16);
  // цвет — нейтральный серый, как разделители строк товара (Figma; не primary/чёрный)
  const [r, g, b] = rgb(line.color);
  expect(Math.max(r, g, b) - Math.min(r, g, b), `${tag}: линия серая (${line.color})`).toBeLessThanOrEqual(30);
  expect(Math.min(r, g, b), `${tag}: линия светлая (${line.color})`).toBeGreaterThanOrEqual(180);
  // под «סה"כ לתשלום» внутри карточки дополнительных линий нет
  const below = m.lines.filter((x) => x.y > m.tot.bottom + 0.5 && x.y < m.card.b - 1.5);
  expect(below, `${tag}: под «סה"כ לתשלום» линий нет`).toEqual([]);

  // порядок и значения: «סכום ביניים» выше «סה"כ לתשלום», подпись справа, сумма слева (RTL), обе ₪105.00
  expect(m.sub.bottom, `${tag}: «סכום ביניים» выше «סה"כ לתשלום»`).toBeLessThanOrEqual(m.tot.top);
  for (const x of [m.sub, m.tot]) {
    expect(x.amt.r, `${tag}: сумма слева от подписи`).toBeLessThanOrEqual(x.lab.l + 0.5);
    expect(x.text, `${tag}: сумма заказа #${ORDER}`).toBe('₪105.00');
  }
  expect(m.docSW, `${tag}: страница без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
}

test.describe('orders — כרטיס הזמנה: קו ההפרדה בסיכום בין «סכום ביניים» ל«סה"כ לתשלום» (#ceadd3)', () => {
  test('1440 (טבלה): בלי קו מעל «סכום ביניים», קו אחד 1px בין הסיכומים, 10px לפני ואחרי; 1382 / 706 / 768 — אותו דבר #ceadd3 @desktop @orders @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    await openOrder650(page);
    for (const [w, h] of [[1440, 900], [1382, 900]] as const) await checkTotals(page, w, h, true);
    for (const [w, h] of [[768, 1024], [706, 900]] as const) await checkTotals(page, w, h);
  });

  test('רגרסיה צר: 1024/1100/1280/1381 עם תפריט צד ו-705 בלי — אותו סיכום וקו אחד בין הסיכומים #ceadd3 @desktop @orders @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    await openOrder650(page);
    for (const [w, h] of [[1024, 768], [1100, 800], [1280, 800], [1381, 900]] as const) await checkTotals(page, w, h, true);
    await checkTotals(page, 705, 900);
  });

  test('טלפון 320/360/390/414 ולרוחב 667×375: בלי קו מעל «סכום ביניים», קו אחד בין הסיכומים #ceadd3 @iphone @orders @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    await openOrder650(page);
    for (const [w, h] of [[320, 568], [360, 740], [390, 844], [414, 896], [667, 375]] as const) await checkTotals(page, w, h);
  });
});
